    static long powerMod(long b, long e, long m) {
        long x = 1;
        while (e > 0) {
            if (e % 2 == 1)
                x = (b * x) % m;
            b = (b * b) % m;
            e /= 2;
        }
        return x;
    }

    static long computeAnswer(long n, long m, int L, int R, long mod) {
        long inv2 = powerMod(2, mod - 2, mod);
        long diff = R - L + 1;
        long p1 = diff / 2;
        long p2 = diff - p1;
        long nm = n * m;
        if (nm % 2 == 1) {
            return powerMod(diff, nm, mod);
        } else {
            long pp1 = diff;
            long pp2 = Math.abs(p1 - p2);
            long opt1 = powerMod(pp1, nm, mod);
            long opt2 = powerMod(pp2, nm, mod);
            long opt = (opt1 + opt2) % mod;
            opt = (opt * inv2) % mod;
            return opt;
        }
    }

    static void process() throws Exception {
        out = new BufferedWriter(new OutputStreamWriter(System.out));
        reader = new InputReader(System.in);

        long n = reader.readInt();
